package com.massivex.android.transfer

import com.google.gson.*
import com.massivex.android.network.*
import com.massivex.massa.*
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test
import java.io.File

internal fun parse(text:String)=ReadJson.parse(HttpPayload(200,"application/json",text.toByteArray()))
internal fun statusJson(now:Long=TEST_TIME)=parse("""{"chain_id":77658377,"version":"MAIN.5.1","current_time":$now,"last_slot":{"period":100,"thread":1},"minimal_fees":"0.001","config":{"operation_validity_periods":10}}""").asJsonObject
internal fun operationJson(s:SignedTransfer,success:Boolean=true)=parse("""[{"id":"${s.draft.operationId}","in_pool":false,"is_operation_final":true,"op_exec_status":$success,"operation":{"id":"${s.draft.operationId}","content_creator_pub_key":"${s.draft.source.publicKey}","content_creator_address":"${s.draft.source.address}","signature":"${s.signature}","content":{"fee":"${s.draft.fee.text}","expire_period":${s.draft.expiry},"op":{"Transaction":{"recipient_address":"${s.draft.recipient}","amount":"${s.draft.amount.text}"}}}}}]""").asJsonArray
private fun rejectsAny(block:()->Unit){try{block();fail("Expected invalid provider evidence rejection")}catch(_:SendFailure){}catch(_:ReadFailure){}catch(_:MassaException){}}
class MainnetSendReadsTest {
    @Test fun exactCurrentStatusFields(){val s=MainnetSendReads.decodeStatus(statusJson(),TEST_TIME,TEST_TIME);assertEquals("0.001",s.fee.text);assertEquals(100uL,s.period);assertEquals(10uL,s.validity)}
    @Test fun wrongChainVersionAndClockRejected(){for(field in listOf("chain_id","version","current_time")){val s=statusJson();when(field){"chain_id"->s.addProperty(field,0);"version"->s.addProperty(field,"MAIN.5.2");else->s.addProperty(field,TEST_TIME+20001)};rejectsAny{MainnetSendReads.decodeStatus(s,TEST_TIME,TEST_TIME)}}}
    @Test fun staleOldAndLongStatusBundleRejected(){rejectsAny{MainnetSendReads.decodeStatus(statusJson(TEST_TIME-20001),TEST_TIME,TEST_TIME)};rejectsAny{MainnetSendReads.decodeStatus(statusJson(),TEST_TIME,TEST_TIME+20001)}}
    @Test fun everyRequiredStatusFieldFailsClosed(){for(field in listOf("chain_id","version","current_time","last_slot","minimal_fees","config")){val s=statusJson();s.remove(field);rejectsAny{MainnetSendReads.decodeStatus(s,TEST_TIME,TEST_TIME)}}}
    @Test fun noNumericFeeOrInvalidSlotCoercion(){val s=statusJson();s.addProperty("minimal_fees",.001);rejectsAny{MainnetSendReads.decodeStatus(s,TEST_TIME,TEST_TIME)};val b=statusJson();b.getAsJsonObject("last_slot").addProperty("period","100");rejectsAny{MainnetSendReads.decodeStatus(b,TEST_TIME,TEST_TIME)}}
    @Test fun minimalFeePrecisionAndValidityBounds(){for(fee in listOf("-1","0.0000000001","1e2","18446744073.709551616")){val s=statusJson();s.addProperty("minimal_fees",fee);rejectsAny{MainnetSendReads.decodeStatus(s,TEST_TIME,TEST_TIME)}};val s=statusJson();s.getAsJsonObject("config").addProperty("operation_validity_periods",1);rejectsAny{MainnetSendReads.decodeStatus(s,TEST_TIME,TEST_TIME)}}
    @Test fun readOnlyPreflightDisclosesOnlyTwoPublicAddresses()=runBlocking{
        val requests=mutableListOf<JsonObject>();val reader=MainnetSendReads(ReadTransport{req->val body=JsonParser.parseString(req.body!!.toString(Charsets.UTF_8)).asJsonObject;requests+=body
            val result=if(body["method"].asString=="get_status")statusJson() else parse("""[{"address":"${source().address}","final_balance":"10","candidate_balance":"9"},{"address":"$recipient","final_balance":"0","candidate_balance":"0"}]""")
            HttpPayload(200,"application/json","""{"jsonrpc":"2.0","id":${body["id"]},"result":$result}""".toByteArray())
        },{TEST_TIME})
        val s=reader.snapshot(source(),recipient);assertEquals("9",s.spendable.text);assertTrue(RecipientCredit.make(MASAmount(1_000_000uL),s).creationPossible)
        assertEquals(listOf("get_status","get_addresses"),requests.map{it["method"].asString});assertEquals(listOf(source().address,recipient),requests.last()["params"].asJsonArray[0].asJsonArray.map{it.asString})
        assertFalse(requests.joinToString().contains("signature"));assertFalse(requests.joinToString().contains("amount"))
    }
    @Test fun wrongChainStopsAddressDisclosure()=runBlocking{var calls=0;val reader=MainnetSendReads(ReadTransport{r->calls++;val q=JsonParser.parseString(r.body!!.toString(Charsets.UTF_8)).asJsonObject;val s=statusJson().apply{addProperty("chain_id",0)};HttpPayload(200,"application/json","""{"jsonrpc":"2.0","id":${q["id"]},"result":$s}""".toByteArray())},{TEST_TIME});try{reader.snapshot(source(),recipient);fail("Wrong chain accepted")}catch(_:SendFailure){};assertEquals(1,calls)}
    @Test fun unsafeFixtureIdentitiesRejectedBeforeAnyNetwork()=runBlocking{var calls=0;val reader=MainnetSendReads(ReadTransport{calls++;throw AssertionError("Network must not run")},{TEST_TIME});try{reader.snapshot(source(),SendIdentityPolicy.unsafe.first());fail("Unsafe recipient allowed")}catch(_:SendFailure){};assertEquals(0,calls)}
    @Test fun missingRecipientBalanceNeverWaivesCreationCost()=runBlocking{val reader=MainnetSendReads(ReadTransport{r->val q=JsonParser.parseString(r.body!!.toString(Charsets.UTF_8)).asJsonObject;val data=if(q["method"].asString=="get_status")statusJson()else parse("""[{"address":"${source().address}","final_balance":"10","candidate_balance":"9"},{"address":"$recipient","final_balance":"0"}]""");HttpPayload(200,"application/json","""{"jsonrpc":"2.0","id":${q["id"]},"result":$data}""".toByteArray())},{TEST_TIME});try{reader.snapshot(source(),recipient);fail("Missing recipient state accepted")}catch(_:ReadFailure){}}
    @Test fun reorderedOrExtraBalanceRowsRejected()=runBlocking{for(data in listOf("[]","[{},{}]","[{},{},{}]")){val reader=MainnetSendReads(ReadTransport{r->val q=JsonParser.parseString(r.body!!.toString(Charsets.UTF_8)).asJsonObject;HttpPayload(200,"application/json","""{"jsonrpc":"2.0","id":${q["id"]},"result":${if(q["method"].asString=="get_status")statusJson()else data}}""".toByteArray())},{TEST_TIME});try{reader.snapshot(source(),recipient);fail("Invalid identity rows accepted")}catch(_:ReadFailure){}}}
    @Test fun emptyMissingPrunedReceiptsRemainUnknown(){val s=signed();val c=VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME);assertEquals(TransferState.UNKNOWN,MainnetSendReads.decodeObservation(parse("[]"),s,c,TEST_TIME).state)}
    @Test fun pendingFlagsNeverBecomeFinal(){val s=signed();for(field in listOf("is_operation_final","op_exec_status")){val rows=operationJson(s);rows[0].asJsonObject.add(field,JsonNull.INSTANCE);if(field=="is_operation_final")assertFalse(MainnetSendReads.decodeObservation(rows,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME).state.terminal)else rejectsAny{MainnetSendReads.decodeObservation(rows,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}}}
    @Test fun exactMatchedSuccessAndFailureReports(){val s=signed();for(outcome in listOf(true,false)){val o=MainnetSendReads.decodeObservation(operationJson(s,outcome),s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME);assertEquals(outcome,o.report!!.success);o.report.validate(s)}}
    @Test fun finalPoolContradictionAndNonBooleanStatusRejected(){val s=signed();for(field in listOf("in_pool","op_exec_status","is_operation_final")){val a=operationJson(s);a[0].asJsonObject.addProperty(field,if(field=="in_pool")"true"else"false");rejectsAny{MainnetSendReads.decodeObservation(a,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}};val a=operationJson(s);a[0].asJsonObject.addProperty("in_pool",true);rejectsAny{MainnetSendReads.decodeObservation(a,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}}
    @Test fun missingCanonicalPayloadNeverAccepted(){val s=signed();val a=operationJson(s);a[0].asJsonObject.remove("operation");rejectsAny{MainnetSendReads.decodeObservation(a,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}}
    @Test fun wrongOuterAndInnerIdsRejected(){val s=signed();for(inner in listOf(false,true)){val a=operationJson(s);val row=a[0].asJsonObject;if(inner)row.getAsJsonObject("operation").addProperty("id",MassaCodec.encode(ByteArray(32){8},"O"))else row.addProperty("id",MassaCodec.encode(ByteArray(32){8},"O"));rejectsAny{MainnetSendReads.decodeObservation(a,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}}}
    @Test fun creatorPublicKeyAddressAndSignatureMustMatchExactly(){val s=signed();for(field in listOf("content_creator_pub_key","content_creator_address","signature")){val a=operationJson(s);a[0].asJsonObject.getAsJsonObject("operation").addProperty(field,when(field){"content_creator_pub_key"->identity(44).publicKey;"content_creator_address"->recipient;else->"invalid"});rejectsAny{MainnetSendReads.decodeObservation(a,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}}}
    @Test fun feeExpiryAmountAndRecipientMismatchRejected(){val s=signed();for(field in listOf("fee","expire_period","amount","recipient_address")){val a=operationJson(s);val c=a[0].asJsonObject.getAsJsonObject("operation").getAsJsonObject("content");val tx=c.getAsJsonObject("op").getAsJsonObject("Transaction");when(field){"fee"->c.addProperty(field,"0.002");"expire_period"->c.addProperty(field,110);"amount"->tx.addProperty(field,"2");else->tx.addProperty(field,identity(44).address)};rejectsAny{MainnetSendReads.decodeObservation(a,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}}}
    @Test fun nonTransactionOrMixedOperationCannotResolveBasicPayment(){val s=signed();val a=operationJson(s);a[0].asJsonObject.getAsJsonObject("operation").getAsJsonObject("content").getAsJsonObject("op").add("RollBuy",JsonNull.INSTANCE);rejectsAny{MainnetSendReads.decodeObservation(a,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}}
    @Test fun duplicateRowsAndMalformedAmountsRejected(){val s=signed();val a=operationJson(s);a.add(a[0].deepCopy());rejectsAny{MainnetSendReads.decodeObservation(a,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)};val b=operationJson(s);b[0].asJsonObject.getAsJsonObject("operation").getAsJsonObject("content").addProperty("fee",1);rejectsAny{MainnetSendReads.decodeObservation(b,s,VerifiedNodeContext(CHAIN,"MAIN.5.1",TEST_TIME),TEST_TIME)}}
    @Test fun rpcPayloadContainsOnlyExistingCanonicalOperationId(){val s=signed();val req=ReadRequest.operation("fixed",s.draft.operationId);val body=JsonParser.parseString(req.body!!.toString(Charsets.UTF_8)).asJsonObject;assertEquals("get_operations",body["method"].asString);assertEquals(s.draft.operationId,body["params"].asJsonArray[0].asJsonArray.single().asString);assertFalse(body.toString().contains(s.signature));assertFalse(body.toString().contains(s.draft.recipient))}
    @Test fun readRequestCannotContainInvalidOperationId(){try{ReadRequest.operation("x","not-an-id");fail("Bad lookup ID accepted")}catch(_:ReadFailure){}}
    @Test fun productionGraphHasOneAuditableGestureOnlyWriteAdapter(){
        val files=File("src/main").walkTopDown().filter{it.extension in setOf("kt","xml")}.toList()
        for(f in files){val text=f.readText();for(method in listOf("execute_sc","buy_rolls","sell_rolls"))assertFalse("Forbidden RPC in ${f.name}",text.contains(method));if(f.name!="MainnetBroadcastTransport.kt")assertFalse("Unexpected write in ${f.name}",text.contains("send_operations"))}
        val model=File("src/main/java/com/massivex/android/SendModel.kt").readText();assertTrue(model.contains("SendCoordinator(reads,ledger,reads,MainnetBroadcastTransport())"));assertFalse(model.contains("BuildConfig.DEBUG"));assertFalse(model.contains("RecordingTransport"));assertTrue(File("src/main/java/com/massivex/android/MainActivity.kt").readText().contains("sendModel.ledger)"))
    }
}
